import React, { useState, useCallback, useRef } from 'react';
import './index.css';
import Cursor from './components/Cursor';
import DrawCanvas from './components/DrawCanvas';
import TypeRenderer from './components/TypeRenderer';
import MetricDisplay from './components/MetricDisplay';
import { analysePath, metricsToType } from './hooks/pathAnalysis';

const PRESET_WORDS = ['FORM', 'DRAPE', 'BODY', 'VOID', 'SEAM'];

const INSTRUCTIONS = [
  { n:'01', text:'Draw any outline in the canvas on the left' },
  { n:'02', text:'The letters respond to your silhouette\'s geometry' },
  { n:'03', text:'Change the word to see different letterforms' },
  { n:'04', text:'Every draw produces a unique typeface' },
];

export default function App() {
  const [metrics,   setMetrics]   = useState(null);
  const [typeProps, setTypeProps] = useState(null);
  const [word,      setWord]      = useState('FORM');
  const [input,     setInput]     = useState('FORM');
  const [hasDrawn,  setHasDrawn]  = useState(false);
  const canvasRef = useRef(null);

  const onPathUpdate = useCallback((pts) => {
    if (pts.length < 8) { setMetrics(null); setTypeProps(null); setHasDrawn(false); return; }
    const m = analysePath(pts);
    const t = metricsToType(m);
    setMetrics(m);
    setTypeProps(t);
    setHasDrawn(true);
  }, []);

  const handleClear = () => {
    canvasRef.current?.clear();
    setMetrics(null);
    setTypeProps(null);
    setHasDrawn(false);
  };

  const applyWord = () => {
    const clean = input.toUpperCase().replace(/[^A-Z]/g, '').slice(0, 10);
    if (clean) setWord(clean);
  };

  return (
    <>
      <Cursor />

      {/* ── Nav ── */}
      <nav style={{ position:'fixed', top:0, left:0, right:0, zIndex:100, display:'flex', alignItems:'center', justifyContent:'space-between', padding:'0 48px', height:56, background:'rgba(242,240,235,0.96)', borderBottom:'1px solid rgba(10,10,10,0.08)', backdropFilter:'blur(12px)' }}>
        <a href="/" style={{ fontSize:12, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(10,10,10,0.45)', transition:'color .2s' }}
          onMouseEnter={e=>e.target.style.color='#0a0a0a'} onMouseLeave={e=>e.target.style.color='rgba(10,10,10,0.45)'}>
          ← Back
        </a>
        <span style={{ fontSize:12, letterSpacing:'0.18em', textTransform:'uppercase', color:'rgba(10,10,10,0.4)' }}>
          Silhouette — Sandra Sæbø
        </span>
        <span style={{ fontSize:12, letterSpacing:'0.14em', color:'rgba(10,10,10,0.3)' }}>2024</span>
      </nav>

      <main style={{ paddingTop:56 }}>

        {/* ── Hero header ── */}
        <div style={{ padding:'72px 48px 60px', borderBottom:'1px solid rgba(10,10,10,0.08)', animation:'fadeUp .8s cubic-bezier(0.16,1,0.3,1) both' }}>
          <p style={{ fontSize:11, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(10,10,10,0.4)', marginBottom:24 }}>
            01 — Creative Direction, Generative Code — 2024
          </p>
          <h1 style={{ fontFamily:'Helvetica Neue,Helvetica,Arial,sans-serif', fontWeight:700, fontSize:'clamp(52px,10vw,140px)', letterSpacing:'-0.05em', lineHeight:0.85, textTransform:'uppercase', color:'#0a0a0a', marginBottom:40 }}>
            Silhouette
          </h1>
          <p style={{ fontSize:17, color:'rgba(10,10,10,0.6)', lineHeight:1.85, fontWeight:300, maxWidth:560 }}>
            Draw a garment outline. The algorithm reads its contour — tension, drape, curvature — and maps those qualities onto a live type system. Every letter becomes a reflection of the shape you drew.
          </p>
        </div>

        {/* ── Type output — big, first thing you see ── */}
        <div style={{ borderBottom:'1px solid rgba(10,10,10,0.08)', background: hasDrawn ? '#0a0a0a' : '#f2f0eb', transition:'background .6s cubic-bezier(0.16,1,0.3,1)', minHeight:240, display:'flex', alignItems:'center', padding:'0 48px', overflow:'hidden', position:'relative' }}>
          {!hasDrawn && (
            <p style={{ fontSize:13, letterSpacing:'0.14em', textTransform:'uppercase', color:'rgba(10,10,10,0.25)', position:'absolute', left:'50%', transform:'translateX(-50%)' }}>
              Draw below to generate type ↓
            </p>
          )}
          <div style={{ width:'100%', height:220 }}>
          <TypeRenderer
            metrics={metrics}
            word={word}
          />
          </div>
          {hasDrawn && (
            <div style={{ position:'absolute', right:48, bottom:20, display:'flex', alignItems:'center', gap:8 }}>
              <span style={{ width:5, height:5, borderRadius:'50%', background:'rgba(242,240,235,0.4)', display:'inline-block', animation:'pulse 2s infinite' }} />
              <span style={{ fontSize:10, letterSpacing:'0.16em', textTransform:'uppercase', color:'rgba(242,240,235,0.4)' }}>Live</span>
            </div>
          )}
        </div>

        {/* ── Controls bar ── */}
        <div style={{ padding:'20px 48px', borderBottom:'1px solid rgba(10,10,10,0.08)', display:'flex', alignItems:'center', gap:24, flexWrap:'wrap', justifyContent:'space-between' }}>
          {/* Word input */}
          <div style={{ display:'flex', alignItems:'center', gap:16, flexWrap:'wrap' }}>
            <span style={{ fontSize:11, letterSpacing:'0.18em', textTransform:'uppercase', color:'rgba(10,10,10,0.4)' }}>Word</span>
            <input
              value={input}
              onChange={e => setInput(e.target.value.toUpperCase().slice(0, 10))}
              onKeyDown={e => e.key === 'Enter' && applyWord()}
              placeholder="TYPE HERE"
              style={{ background:'transparent', border:'none', borderBottom:'1px solid rgba(10,10,10,0.2)', color:'#0a0a0a', fontFamily:'Helvetica Neue,sans-serif', fontSize:14, letterSpacing:'0.1em', padding:'4px 0', width:120, outline:'none', textTransform:'uppercase' }}
            />
            <button onClick={applyWord} data-hover
              style={{ fontSize:11, letterSpacing:'0.14em', textTransform:'uppercase', padding:'6px 16px', border:'1px solid rgba(10,10,10,0.2)', color:'rgba(10,10,10,0.6)', transition:'all .2s' }}
              onMouseEnter={e=>{e.currentTarget.style.background='#0a0a0a';e.currentTarget.style.color='#f2f0eb'}}
              onMouseLeave={e=>{e.currentTarget.style.background='transparent';e.currentTarget.style.color='rgba(10,10,10,0.6)'}}>
              Apply
            </button>
          </div>

          {/* Preset words */}
          <div style={{ display:'flex', gap:8, flexWrap:'wrap' }}>
            {PRESET_WORDS.map(w => (
              <button key={w} onClick={() => { setWord(w); setInput(w); }} data-hover
                style={{ fontSize:11, letterSpacing:'0.12em', textTransform:'uppercase', padding:'5px 14px', border:`1px solid ${word===w?'rgba(10,10,10,0.6)':'rgba(10,10,10,0.15)'}`, color:word===w?'#0a0a0a':'rgba(10,10,10,0.4)', background:word===w?'rgba(10,10,10,0.05)':'transparent', transition:'all .2s' }}>
                {w}
              </button>
            ))}
          </div>

          {/* Clear */}
          <button onClick={handleClear} data-hover
            style={{ fontSize:11, letterSpacing:'0.14em', textTransform:'uppercase', padding:'6px 16px', border:'1px solid rgba(10,10,10,0.15)', color:'rgba(10,10,10,0.4)', transition:'all .2s' }}
            onMouseEnter={e=>{e.currentTarget.style.borderColor='rgba(10,10,10,0.4)';e.currentTarget.style.color='#0a0a0a'}}
            onMouseLeave={e=>{e.currentTarget.style.borderColor='rgba(10,10,10,0.15)';e.currentTarget.style.color='rgba(10,10,10,0.4)'}}>
            Clear
          </button>
        </div>

        {/* ── Main tool: draw left, metrics right ── */}
        <div style={{ display:'grid', gridTemplateColumns:'1fr 320px', minHeight:500, borderBottom:'1px solid rgba(10,10,10,0.08)' }}>

          {/* Drawing canvas */}
          <div style={{ borderRight:'1px solid rgba(10,10,10,0.08)', position:'relative' }}>
            {!hasDrawn && (
              <div style={{ position:'absolute', inset:0, display:'flex', alignItems:'center', justifyContent:'center', pointerEvents:'none', zIndex:1 }}>
                <div style={{ textAlign:'center' }}>
                  <p style={{ fontSize:13, letterSpacing:'0.14em', textTransform:'uppercase', color:'rgba(10,10,10,0.22)', marginBottom:8 }}>Draw a silhouette here</p>
                  <p style={{ fontSize:11, color:'rgba(10,10,10,0.18)', letterSpacing:'0.06em' }}>Any shape — garment, body, gesture</p>
                </div>
              </div>
            )}
            <DrawCanvas
              ref={canvasRef}
              onPathUpdate={onPathUpdate}
              width={900}
              height={600}
            />
          </div>

          {/* Metrics sidebar */}
          <div style={{ padding:'36px 32px', display:'flex', flexDirection:'column', justifyContent:'space-between' }}>
            <MetricDisplay metrics={metrics} typeProps={typeProps} />

            {/* Instructions */}
            <div style={{ marginTop:32, borderTop:'1px solid rgba(10,10,10,0.08)', paddingTop:24 }}>
              {INSTRUCTIONS.map(({ n, text }) => (
                <div key={n} style={{ display:'flex', gap:12, marginBottom:14 }}>
                  <span style={{ fontSize:10, fontFamily:'monospace', color:'rgba(10,10,10,0.3)', flexShrink:0, paddingTop:1 }}>{n}</span>
                  <span style={{ fontSize:12, color:'rgba(10,10,10,0.45)', lineHeight:1.6, letterSpacing:'0.02em' }}>{text}</span>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* ── How it works ── */}
        <div style={{ display:'grid', gridTemplateColumns:'repeat(auto-fit,minmax(240px,1fr))', borderBottom:'1px solid rgba(10,10,10,0.08)' }}>
          {[
            { label:'Drawing',    body:'Bézier-smoothed canvas paths, sampled every 3px for contour precision.' },
            { label:'Analysis',   body:'5 geometric metrics: drape (vertical centre of mass), curvature, tension, width ratio, asymmetry.' },
            { label:'Mapping',    body:'Metrics drive font-weight (100–800), horizontal stretch (60–140%), and italic angle.' },
            { label:'Physics',    body:'Spring physics (stiffness 60, damping 11) animate every transition — no easing curves, real force simulation.' },
          ].map(({ label, body }) => (
            <div key={label} style={{ padding:'44px 36px', borderRight:'1px solid rgba(10,10,10,0.06)' }}>
              <p style={{ fontSize:11, letterSpacing:'0.18em', textTransform:'uppercase', color:'rgba(10,10,10,0.35)', marginBottom:14 }}>{label}</p>
              <p style={{ fontSize:14, color:'rgba(10,10,10,0.65)', lineHeight:1.8, fontWeight:300 }}>{body}</p>
            </div>
          ))}
        </div>

        {/* ── Footer ── */}
        <div style={{ padding:'32px 48px', display:'flex', justifyContent:'space-between', alignItems:'center', flexWrap:'wrap', gap:16 }}>
          <a href="/" style={{ fontSize:12, letterSpacing:'0.1em', textTransform:'uppercase', color:'rgba(10,10,10,0.4)', borderBottom:'1px solid rgba(10,10,10,0.15)', paddingBottom:2, transition:'all .2s' }}
            onMouseEnter={e=>{e.currentTarget.style.color='#0a0a0a';e.currentTarget.style.borderColor='rgba(10,10,10,0.5)'}}
            onMouseLeave={e=>{e.currentTarget.style.color='rgba(10,10,10,0.4)';e.currentTarget.style.borderColor='rgba(10,10,10,0.15)'}}>
            ← All projects
          </a>
          <span style={{ fontSize:12, color:'rgba(10,10,10,0.25)' }}>Sandra Sæbø · Silhouette · 2024</span>
        </div>
      </main>
    </>
  );
}
